-- 唐朝历史事件 seed（618—907）
-- 字段顺序与 schema.sql 一致；坐标为事件核心地点的经纬度。
-- category 取值：era 时代格局 / figure 名人轨迹 / military 军事·领土 / economy 经济变革 / invention 重要发明

INSERT OR IGNORE INTO dynasties (id, name, start_year, end_year) VALUES ('tang', '唐朝', 618, 907);

INSERT OR IGNORE INTO events (dynasty_id, year, year_end, lng, lat, short, title, detail, impact, place, category) VALUES
  ('tang', 618, 618, 108.95, 34.27, '李渊建唐', '李渊称帝 · 唐朝建立', '隋末群雄并起，太原留守李渊于晋阳起兵，攻占长安后废隋恭帝，即皇帝位，国号唐，都长安。', '唐朝开国，继承隋制并加以完善，开启此后近三百年的中国封建社会鼎盛时代。', '长安（今陕西西安）', 'era'),
  ('tang', 621, 621, 113.1, 34.85, '虎牢关之战', '虎牢关之战 · 一战擒两王', '李世民率精骑据虎牢关迎击窦建德十万大军，窦建德兵败被擒，王世充随之出降，中原底定。', '李世民一战擒两王，奠定唐定鼎天下的基础，河北、河南尽归唐朝。', '虎牢关（今河南荥阳西北）', 'military'),
  ('tang', 626, 626, 108.95, 34.27, '玄武门之变', '玄武门之变 · 太宗即位', '李世民在长安玄武门伏杀太子李建成、齐王李元吉，旋被立为太子，不久受禅即皇帝位。', '玄武门之变开启贞观之治，李世民以「以史为鉴」之姿整顿朝纲。', '长安·玄武门', 'era'),
  ('tang', 627, 649, 108.95, 34.27, '贞观之治', '贞观之治 · 盛世奠基', '唐太宗虚心纳谏、任用房玄龄、杜如晦、魏徵等贤臣，轻徭薄赋、劝课农桑，社会安定、经济复苏。', '贞观之治为盛唐奠定制度与人口基础，成为后世称颂的治世典范。', '长安', 'era'),
  ('tang', 629, 645, 108.95, 34.27, '玄奘西行', '玄奘西行取经', '玄奘为求佛法违禁西行，历尽艰险抵达天竺那烂陀寺，遍学五印佛法，贞观十九年携经论六百余部归国。', '玄奘译经并著《大唐西域记》，成为中印文化交流的重要桥梁。', '长安—天竺', 'figure'),
  ('tang', 630, 630, 111.7, 40.3, '灭东突厥', '李靖袭定襄 · 灭东突厥', '李靖率精骑夜袭定襄、直捣颉利可汗牙帐，次年颉利被俘，东突厥灭亡，北方边患解除。', '唐太宗被诸蕃尊为「天可汗」，唐朝声威远播漠北。', '定襄（今内蒙古和林格尔一带）', 'military'),
  ('tang', 640, 640, 89.2, 42.9, '置安西都护府', '设安西都护府 · 经略西域', '唐灭高昌后设安西都护府于交河城，统辖西域军政，保障丝绸之路畅通。', '安西都护府成为唐经营西域的支点，商旅往来获得军事保护。', '交河城（今新疆吐鲁番）', 'military'),
  ('tang', 641, 641, 91.1, 29.65, '文成公主入藏', '文成公主和亲吐蕃', '唐太宗许宗室女文成公主嫁吐蕃赞普松赞干布，公主携工匠、经史、农艺入藏。', '唐蕃和亲促进汉藏交流，大昭寺、小昭寺即与此时营建相关。', '逻些（今西藏拉萨）', 'figure'),
  ('tang', 649, 649, 108.95, 34.27, '太宗崩', '唐太宗崩 · 高宗即位', '唐太宗病逝于含风殿，太子李治即位为高宗，贞观之治落幕。', '唐高宗继承贞观基业，初年仍有「永徽之治」的美誉。', '长安·含风殿', 'era'),
  ('tang', 657, 657, 83.0, 41.7, '灭西突厥', '灭西突厥 · 安西迁龟兹', '苏定方率军进击西突厥，大破沙钵罗可汗，西突厥灭亡，唐于其地分置昆陵、濛池都护府。', '西突厥平定后，唐朝对西域的统治扩展到中亚两河流域，安西都护府迁治龟兹。', '龟兹（今新疆库车）', 'military'),
  ('tang', 663, 663, 126.7, 36.0, '白江口之战', '白江口之战 · 唐罗败倭', '唐将刘仁轨率水军在白江口迎击日本与百济残余联军，四战皆捷，焚毁倭船四百余艘。', '此战奠定唐朝在东北亚的绝对权威，日本此后数百年不再涉足朝鲜半岛。', '白江口（今韩国锦江入海口）', 'military'),
  ('tang', 690, 690, 112.45, 34.62, '武周代唐', '武则天称帝 · 改唐为周', '武则天废睿宗，改唐为周，称圣神皇帝，定都洛阳，是中国历史上唯一的女皇帝。', '武周上承贞观、下启开元，武则天整顿吏治、发展科举，为盛唐积蓄力量。', '神都洛阳', 'era'),
  ('tang', 705, 705, 112.45, 34.62, '神龙政变', '神龙政变 · 李唐复辟', '宰相张柬之等率禁军逼武则天退位，迎中宗李显复位，复国号唐，武周结束。', '政变后李唐复辟，但韦后、太平公主相继擅权，政局一度反复动荡。', '洛阳·玄武门', 'era'),
  ('tang', 713, 741, 108.95, 34.27, '开元盛世', '开元盛世 · 黄金时代', '唐玄宗即位后励精图治，任用姚崇、宋璟，整顿吏治、均田括户，天下大治，户数增至近千万。', '开元盛世是唐朝乃至中国古代社会的黄金时代，长安成为当时世界性大都市。', '长安', 'era'),
  ('tang', 751, 751, 71.4, 42.9, '怛罗斯之战', '怛罗斯之战 · 唐军败于大食', '高仙芝率唐军与阿拉伯（黑衣大食）会战于怛罗斯，因葛逻禄临阵倒戈而败，两万唐军被俘。', '此战使唐对中亚的扩张止步，造纸术等经战俘西传，阿拉伯势力东进。', '怛罗斯（今哈萨克斯坦塔拉兹一带）', 'military'),
  ('tang', 755, 763, 116.4, 39.9, '安史之乱', '安史之乱 · 唐由盛转衰', '安禄山、史思明以讨杨国忠为名自范阳起兵，叛军两月内攻陷洛阳、长安，唐玄宗出奔四川。', '安史之乱是唐朝由盛转衰的转折点，此后藩镇割据、宦官专权、党争交相为患。', '范阳（今北京）', 'military'),
  ('tang', 756, 756, 108.5, 34.3, '马嵬驿兵变', '马嵬驿兵变 · 贵妃殒命', '唐玄宗西逃途中，禁军于马嵬驿哗变，杀杨国忠并逼缢杨贵妃，玄宗被迫入蜀。', '贵妃之死成为安史之乱的标志性一幕，后世诗人反复吟咏其事。', '马嵬驿（今陕西兴平西）', 'figure'),
  ('tang', 763, 763, 108.95, 34.27, '乱平藩镇兴', '安史之乱平定', '史朝义穷蹙自缢，历时八年的安史之乱告平，然河朔三镇自此成藩镇割据之局。', '平叛后唐廷无力收回河北，藩镇林立的局面一直延续到唐亡。', '长安', 'era'),
  ('tang', 780, 780, 108.95, 34.27, '两税法', '杨炎推行两税法', '宰相杨炎奏请废止租庸调，改行以资产为宗的两税法，夏秋两季分两次征收。', '两税法确立以土地与资产定税的新制，为后世各代税制奠定基础。', '长安', 'economy'),
  ('tang', 810, 810, 108.95, 34.27, '飞钱问世', '飞钱出现 · 汇兑雏形', '唐宪宗时出现「飞钱」（便换），商人在京将货款交予官府或富商，凭券赴地方兑取现钱。', '飞钱是中国汇兑制度与纸币的先声，反映唐中期商业信用的发展。', '长安', 'economy'),
  ('tang', 868, 868, 94.7, 40.1, '金刚经雕版', '《金刚经》雕版印刷', '信士王玠为双亲祈福，出资雕版印造《金刚经》，卷末题记刻「咸通九年四月十五日」。', '这是迄今有确切纪年的最早雕版印刷品，1900 年出土于敦煌藏经洞。', '敦煌（今甘肃敦煌）', 'invention'),
  ('tang', 875, 884, 115.5, 35.2, '黄巢起义', '黄巢起义 · 王仙芝首义', '王仙芝、黄巢相继起兵于长垣、冤句，黄巢率义军转战大半个中国，自称「冲天大将军」。', '起义沉重打击唐朝统治基础，揭开唐末大动乱的序幕。', '冤句（今山东菏泽一带）', 'era'),
  ('tang', 880, 880, 108.95, 34.27, '黄巢克长安', '黄巢入长安称帝', '黄巢义军攻破潼关、入长安，即帝位建国号大齐，唐僖宗出逃成都。', '黄巢虽据长安，但缺乏稳固后方，唐朝中央统治已名存实亡。', '长安', 'military'),
  ('tang', 884, 884, 117.6, 36.2, '黄巢败亡', '黄巢败死狼虎谷', '义军粮尽，黄巢败退山东，在狼虎谷为外甥林言所杀，起义历时十年而终。', '黄巢起义后，朱温等藩镇势力坐大，唐朝中央政权形同虚设。', '狼虎谷（今山东莱芜一带）', 'military'),
  ('tang', 907, 907, 114.35, 34.78, '朱温篡唐', '朱温灭唐 · 后梁建立', '朱温废唐哀帝，自立为帝，国号梁，史称后梁，唐朝灭亡。', '朱温灭唐终结了延续二百八十九年的大唐帝国，中国进入五代十国分裂时期。', '汴州（今河南开封）', 'era');
